func linux_recvmsgRaw(fd int, p, oob []byte, flags int, rsa *Linux_RawSockaddrAny) (n, oobn int, recvflags int, err error) {
	var msg Linux_Msghdr
	msg.Name = (*byte)(unsafe.Pointer(rsa))
	msg.Namelen = uint32(Linux_SizeofSockaddrAny)
	var iov Linux_Iovec
	if len(p) > 0 {
		iov.Base = &p[0]
		iov.SetLen(len(p))
	}
	var dummy byte
	if len(oob) > 0 {
		if len(p) == 0 {
			var sockType int
			sockType, err = Linux_GetsockoptInt(fd, Linux_SOL_SOCKET, Linux_SO_TYPE)
			if err != nil {
				return
			}
			// receive at least one normal byte
			if sockType != Linux_SOCK_DGRAM {
				iov.Base = &dummy
				iov.SetLen(1)
			}
		}
		msg.Control = &oob[0]
		msg.SetControllen(len(oob))
	}
	msg.Iov = &iov
	msg.Iovlen = 1
	if n, err = linux_recvmsg(fd, &msg, flags); err != nil {
		return
	}
	oobn = int(msg.Controllen)
	recvflags = int(msg.Flags)
	return
}

func linux_sendmsgN(fd int, p, oob []byte, ptr unsafe.Pointer, salen linux__Socklen, flags int) (n int, err error) {
	var msg Linux_Msghdr
	msg.Name = (*byte)(ptr)
	msg.Namelen = uint32(salen)
	var iov Linux_Iovec
	if len(p) > 0 {
		iov.Base = &p[0]
		iov.SetLen(len(p))
	}
	var dummy byte
	if len(oob) > 0 {
		if len(p) == 0 {
			var sockType int
			sockType, err = Linux_GetsockoptInt(fd, Linux_SOL_SOCKET, Linux_SO_TYPE)
			if err != nil {
				return 0, err
			}
			// send at least one normal byte
			if sockType != Linux_SOCK_DGRAM {
				iov.Base = &dummy
				iov.SetLen(1)
			}
		}
		msg.Control = &oob[0]
		msg.SetControllen(len(oob))
	}
	msg.Iov = &iov
	msg.Iovlen = 1
	if n, err = linux_sendmsg(fd, &msg, flags); err != nil {
		return 0, err
	}
	if len(oob) > 0 && len(p) == 0 {
		n = 0
	}
	return n, nil
}

