//sys	ptrace(request int, pid int, addr uintptr, data uintptr) (err error)
//sys	ptracePtr(request int, pid int, addr uintptr, data unsafe.Pointer) (err error) = SYS_PTRACE

func linux_ptracePeek(req int, pid int, addr uintptr, out []byte) (count int, err error) {
	// The peek requests are machine-size oriented, so we wrap it
	// to retrieve arbitrary-length data.

	// The ptrace syscall differs from glibc's ptrace.
	// Peeks returns the word in *data, not as the return value.

	var buf [linux_sizeofPtr]byte

	// Leading edge. PEEKTEXT/PEEKDATA don't require aligned
	// access (PEEKUSER warns that it might), but if we don't
	// align our reads, we might straddle an unmapped page
	// boundary and not get the bytes leading up to the page
	// boundary.
	n := 0
	if addr%linux_sizeofPtr != 0 {
		err = linux_ptracePtr(req, pid, addr-addr%linux_sizeofPtr, unsafe.Pointer(&buf[0]))
		if err != nil {
			return 0, err
		}
		n += copy(out, buf[addr%linux_sizeofPtr:])
		out = out[n:]
	}

	// Remainder.
	for len(out) > 0 {
		// We use an internal buffer to guarantee alignment.
		// It's not documented if this is necessary, but we're paranoid.
		err = linux_ptracePtr(req, pid, addr+uintptr(n), unsafe.Pointer(&buf[0]))
		if err != nil {
			return n, err
		}
		copied := copy(out, buf[0:])
		n += copied
		out = out[copied:]
	}

	return n, nil
}

func Linux_PtracePeekText(pid int, addr uintptr, out []byte) (count int, err error) {
	return linux_ptracePeek(Linux_PTRACE_PEEKTEXT, pid, addr, out)
}

func Linux_PtracePeekData(pid int, addr uintptr, out []byte) (count int, err error) {
	return linux_ptracePeek(Linux_PTRACE_PEEKDATA, pid, addr, out)
}

func linux_ptracePoke(pokeReq int, peekReq int, pid int, addr uintptr, data []byte) (count int, err error) {
	// As for ptracePeek, we need to align our accesses to deal
	// with the possibility of straddling an invalid page.

	// Leading edge.
	n := 0
	if addr%linux_sizeofPtr != 0 {
		var buf [linux_sizeofPtr]byte
		err = linux_ptracePtr(peekReq, pid, addr-addr%linux_sizeofPtr, unsafe.Pointer(&buf[0]))
		if err != nil {
			return 0, err
		}
		n += copy(buf[addr%linux_sizeofPtr:], data)
		word := *((*uintptr)(unsafe.Pointer(&buf[0])))
		err = linux_ptrace(pokeReq, pid, addr-addr%linux_sizeofPtr, word)
		if err != nil {
			return 0, err
		}
		data = data[n:]
	}

	// Interior.
	for len(data) > linux_sizeofPtr {
		word := *((*uintptr)(unsafe.Pointer(&data[0])))
		err = linux_ptrace(pokeReq, pid, addr+uintptr(n), word)
		if err != nil {
			return n, err
		}
		n += linux_sizeofPtr
		data = data[linux_sizeofPtr:]
	}

	// Trailing edge.
	if len(data) > 0 {
		var buf [linux_sizeofPtr]byte
		err = linux_ptracePtr(peekReq, pid, addr+uintptr(n), unsafe.Pointer(&buf[0]))
		if err != nil {
			return n, err
		}
		copy(buf[0:], data)
		word := *((*uintptr)(unsafe.Pointer(&buf[0])))
		err = linux_ptrace(pokeReq, pid, addr+uintptr(n), word)
		if err != nil {
			return n, err
		}
		n += len(data)
	}

	return n, nil
}

func Linux_PtracePokeText(pid int, addr uintptr, data []byte) (count int, err error) {
	return linux_ptracePoke(Linux_PTRACE_POKETEXT, Linux_PTRACE_PEEKTEXT, pid, addr, data)
}

func Linux_PtracePokeData(pid int, addr uintptr, data []byte) (count int, err error) {
	return linux_ptracePoke(Linux_PTRACE_POKEDATA, Linux_PTRACE_PEEKDATA, pid, addr, data)
}

